--
-- Table structure for table `funders`
--

DROP TABLE IF EXISTS `funders`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `funders` (
  `id` varchar(36) NOT NULL,
  `institution_name` varchar(200) NOT NULL,
  `institution_type` varchar(20) NOT NULL,
  `unified_social_credit_code` varchar(18) NOT NULL,
  `business_license_url` text,
  `financial_license_url` text,
  `account_opening_permit_url` text,
  `contact_person` varchar(100) DEFAULT NULL,
  `contact_phone` varchar(50) DEFAULT NULL,
  `bank_name` varchar(200) DEFAULT NULL,
  `bank_account` varchar(100) DEFAULT NULL,
  `account_name` varchar(200) DEFAULT NULL,
  `cumulative_credit_limit` decimal(20,2) NOT NULL DEFAULT '0.00',
  `current_loan_balance` decimal(20,2) NOT NULL DEFAULT '0.00',
  `status` varchar(20) NOT NULL DEFAULT 'active',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `deleted_at` datetime DEFAULT NULL,
  `business_license_name` varchar(255) DEFAULT NULL,
  `financial_license_name` varchar(255) DEFAULT NULL,
  `account_opening_permit_name` varchar(255) DEFAULT NULL,
  `org_id` varchar(36) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `unified_social_credit_code` (`unified_social_credit_code`),
  KEY `idx_institution_type` (`institution_type`),
  KEY `idx_status` (`status`),
  KEY `idx_unified_social_credit_code` (`unified_social_credit_code`),
  KEY `idx_deleted_at` (`deleted_at`),
  KEY `idx_funders_deleted_at` (`deleted_at`),
  KEY `idx_funders_org_id` (`org_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

